await new Promise((resolve) => gapi.load('picker', resolve));
if (!weft.clientId) throw new Error('this connection has no OAuth app; the Google picker only grants files to an app');
let view = new google.picker.DocsView();
if (weft.mimeTypes.length > 0) view = view.setMimeTypes(weft.mimeTypes.join(','));
new google.picker.PickerBuilder()
  .setOAuthToken(weft.token)
  .setAppId(weft.clientId.split('-')[0])
  .addView(view)
  .setCallback((data) => {
    const action = data[google.picker.Response.ACTION];
    if (action === google.picker.Action.PICKED) {
      const doc = data[google.picker.Response.DOCUMENTS][0];
      weft.done({ id: doc.id, label: doc.name || doc.id });
    } else if (action === google.picker.Action.CANCEL) {
      weft.cancel();
    }
  })
  .build()
  .setVisible(true);

